@import url('https://fonts.googleapis.com/css2?family=Zen+Kaku+Gothic+New:wght@400;500;700;900&family=Zen+Maru+Gothic:wght@400;500;700;900&display=swap');

/* =========================================================
   RESET / BASE
========================================================== */

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  overflow-x: hidden;
}

body {
  font-family: 'Zen Kaku Gothic New', -apple-system, BlinkMacSystemFont, 'Hiragino Kaku Gothic ProN', sans-serif;
  color: #1e2a35;
  background: #ffffff;
  line-height: 1.7;
  -webkit-font-smoothing: antialiased;
  overflow-x: hidden;
}

a {
  color: inherit;
  text-decoration: none;
}

ul {
  list-style: none;
}

img {
  max-width: 100%;
  display: block;
}

/* =========================================================
   SHARED / UTILITY
========================================================== */

:root {
  --color-blue: #3ca8d0;
  --color-blue-dark: #2f8fb3;
  --color-blue-light: #eaf4fb;
  --color-indigo: #4d7ff1;
  --color-text-dark: #1e2a35;
  --color-text-body: #4a5560;
  --color-text-muted: #8b98a3;
  --color-purple: #8b7cd8;
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  border-radius: 999px;
  font-weight: 700;
  white-space: nowrap;
  cursor: pointer;
  border: none;
  transition: transform 0.15s ease, box-shadow 0.15s ease, opacity 0.15s ease;
}

.btn:hover {
  transform: translateY(-1px);
  opacity: 0.94;
}

.btn-blue {
  background: var(--color-blue);
  color: #fff;
  font-size: 20px;
  font-weight: 700;
  line-height: 1;
  letter-spacing: 0.05em;
  padding: 13px 24px;
}

/* hero-top-button stays hidden — it's a separate floating button over
   the hero photo, not part of the header bar shown in the nav screenshot. */
.hero-top-button {
  display: none;
}

/* Placeholder image treatment until real photography is dropped in */
.image-placeholder {
  background: linear-gradient(135deg, #dce8f0, #eef3f6);
  display: flex;
  align-items: center;
  justify-content: center;
  color: #9fb0bd;
  font-size: 15px;
  letter-spacing: 0.1em;
  font-weight: 700;
}

/* =========================================================
   HEADER
========================================================== */

.site-header {
  background: rgba(255, 255, 255, 0.78);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  padding: 16px 48px;
  position: sticky;
  top: 0;
  z-index: 50;
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 32px;
  max-width: 1440px;
  margin: 0 auto;
}

.main-nav {
  display: flex;
  align-items: center;
  gap: 32px;
  flex: 1;
  justify-content: center;
}

.main-nav a {
  color: #323b4d;
  font-size: 15px;
  font-weight: 500;
  white-space: nowrap;
  text-decoration: none;
  transition: color 0.15s ease;
}

.main-nav a:hover {
  color: var(--color-indigo);
}

.header-buttons {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-shrink: 0;
}

.header-buttons .btn {
  font-size: 14px;
  line-height: 1;
  padding: 11px 20px;
  letter-spacing: 0.02em;
}

.header-buttons .btn-blue {
  background: var(--color-blue);
}

.header-buttons .btn-purple {
  background: var(--color-indigo);
  color: #fff;
}

.logo {
  display: flex;
  flex-direction: column;
  align-items: center;
}

/* Remove the browser's default focus outline on the logo link —
   it was rendering as a boxed frame around the whole lockup. */
.logo:focus,
.logo:focus-visible {
  outline: none;
}

.logo-top-row {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  column-gap: 10px;
}

.logo-main-placeholder {
  background-image: url('data:image/png;base64,');
  background-size: contain;
  background-repeat: no-repeat;
  background-position: left center;
  width: 110px;
  height: 22px;
  display: inline-block;
  font-size: 0;
  color: transparent;
}

.logo-jp {
  font-family: 'Zen Maru Gothic', sans-serif;
  font-size: 20px;
  font-weight: 400;
  line-height: 1;
  letter-spacing: 0.04em;
  color: #18a2ac;
  white-space: nowrap;
}

.logo-sub {
  font-family: 'Zen Kaku Gothic New', sans-serif;
  font-size: 12px;
  font-weight: 400;
  line-height: 1;
  letter-spacing: 0.05em;
  color: #9aa7b1;
  margin-top: 4px;
}


/* =========================================================
   KIMOCHI WORDMARK
   Reusable "kimochi コーチング" brand mark — the same script
   logotype used in the header and the "why coaching" section,
   paired with コーチング in Zen Maru Gothic. Sized in em so it
   scales cleanly wherever it's dropped in (comparison tables,
   the support-flow diagram, etc.) — just set font-size on the
   parent and this scales with it.
   ========================================================= */

.kimochi-wordmark {
  display: inline-flex;
  align-items: center;
  gap: 0.28em;

  vertical-align: middle;
}

.kimochi-wordmark-logo {
  display: inline-block;

  width: 5.5em;
  height: 1.1em;

  background-image: url('data:image/png;base64,');
  background-size: contain;
  background-repeat: no-repeat;
  background-position: left center;

  flex-shrink: 0;
}

.kimochi-wordmark-jp {
  font-family: "Zen Maru Gothic", "Zen Kaku Gothic New", sans-serif;
  font-weight: 400;
  line-height: 1;
  letter-spacing: 0.01em;
  white-space: nowrap;
}

/* =========================================================
   HERO SECTION
========================================================== */

.hero-section {
  position: relative;
  overflow: hidden;
}

.hero-image {
  position: absolute;
  inset: 0;
  z-index: 0;
  background-image: url('data:image/jpeg;base64,');
  background-size: cover;
  background-position: center 30%;
}

.hero-image span {
  display: none;
}

.hero-image::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(
    to right,
    #ffffff 0%,
    #ffffff 38%,
    rgba(255, 255, 255, 0.88) 48%,
    rgba(255, 255, 255, 0.35) 60%,
    rgba(255, 255, 255, 0) 72%
  );
}

.hero-overlay {
  position: relative;
  z-index: 1;
  max-width: 1440px;
  margin: 0 auto;
  padding: 56px 48px 0;
  min-height: 660px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
}

.hero-content {
  max-width: 600px;
  padding-top: 36px;
}

.hero-eyebrow {
  display: inline-block;
  white-space: nowrap;
  background: #ffffff;
  color: #486e7f;
  font-family: 'Zen Kaku Gothic New', sans-serif;
  font-size: 24px;
  font-weight: 400;
  line-height: 1;
  letter-spacing: 0.05em;
  padding: 11px 20px;
  border: 1px solid #3ca8d0;
  border-radius: 6px;
  margin-bottom: 30px;
}

.hero-eyebrow-highlight {
  color: #3ca8d0;
  font-weight: 700;
}

.hero-content h1 {
  font-family: 'Zen Kaku Gothic New', sans-serif;
  font-size: 50px;
  line-height: 1;
  font-weight: 500;
  color: #323b4d;
  margin-bottom: 26px;
  letter-spacing: 0.05em;
}

.hero-content h1 .h1-lead {
  display: inline-block;
  font-size: 44px;
  color: #486e7f;
  margin-bottom: 8px;
}

.hero-description {
  font-family: 'Zen Kaku Gothic New', sans-serif;
  font-size: 18px;
  font-weight: 400;
  line-height: 1.8;
  letter-spacing: 0.05em;
  color: #323b4d;
  margin-bottom: 30px;
}

.hero-cta {
  background: var(--color-indigo);
  color: #fff;
  font-family: 'Zen Kaku Gothic New', sans-serif;
  font-size: 20px;
  font-weight: 700;
  line-height: 1;
  letter-spacing: 0.05em;
  padding: 17px 34px;
  box-shadow: 0 10px 24px rgba(77, 106, 241, 0.35);
}

.hero-note {
  font-family: 'Zen Kaku Gothic New', sans-serif;
  font-size: 14px;
  font-weight: 400;
  line-height: 1.8;
  letter-spacing: 0.05em;
  color: #486e7f;
  margin-top: 16px;
}

/* ---- hero stat circles ---- */

.hero-stats {
  display: flex;
  align-items: flex-end;
  justify-content: flex-end;
  gap: 11px;
  margin-top: 24px;
}

.hero-stat {
  width: 138px;
  height: 138px;
  min-height: 0;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.95);
  border: 1px solid rgba(210, 230, 238, 0.5);
  box-shadow: inset 0 0 0 2px rgba(163, 196, 209, 0.55);

  /* A fixed-height row for the label + a flexible row for the
     number/strong text — not a single centered flex column — so
     the label always lands at the same offset from the top
     across all three circles. Centering the whole label+strong
     block as one group (the old approach) let each circle's
     label drift up/down depending on how tall its own number
     text happened to render (mixed 30px digits + 19px kanji on
     the same line don't always report identical browser line-box
     heights even with an equal declared line-height). */
  display: grid;
  grid-template-rows: 20px 1fr;
  row-gap: 4px;
  align-items: center;
  justify-items: center;

  text-align: center;
  padding: 24px 12px 12px;
  box-sizing: border-box;
  flex-shrink: 0;
  overflow: hidden;
}

.stat-label {
  font-family: 'Zen Kaku Gothic New', sans-serif;
  font-size: 12px;
  font-weight: 700;
  line-height: 1.5;
  letter-spacing: 0.1em;
  text-align: center;
  color: #8fa9ba;
  margin-bottom: 0px;
  white-space: nowrap;
}

.hero-stat strong {
  font-family: 'Zen Kaku Gothic New', sans-serif;
  font-size: 19px;
  font-weight: 700;
  line-height: 30px;
  letter-spacing: 0;
  text-align: center;
  color: var(--color-text-dark);
  white-space: normal;
  word-break: keep-all;
}

.hero-stat strong em {
  font-style: normal;
  font-weight: 700;
  font-size: 30px;
  line-height: 30px;
  color: var(--color-blue);
}

.hero-stat:first-child strong em {
  font-size: 20px;
  line-height: 30px;
}

/* =========================================================
   HERO FEATURES BAR
========================================================== */

.hero-features {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 64px;
  background: #ffffff;
  padding: 30px 48px;
  flex-wrap: wrap;
}

.feature-item {
  display: flex;
  align-items: center;
  gap: 16px;
}

.feature-label {
  flex-shrink: 0;
  background: var(--color-blue);
  color: #fff;
  font-size: 15px;
  font-weight: 700;
  padding: 9px 15px;
  border-radius: 6px;
}

.feature-item strong {
  font-family: 'Zen Kaku Gothic New', sans-serif;
  font-size: 16px;
  font-weight: 400;
  line-height: 1.5;
  letter-spacing: 0.05em;
  color: var(--color-text-dark);
}

/* =========================================================
   RESPONSIVE (baseline for this section only)
========================================================== */

@media (max-width: 900px) {
  .hero-overlay {
    padding: 6px 24px 0;
    min-height: 0;
  }
  .hero-content {
    padding-top: 6px;
  }
  .hero-content h1 {
    font-size: 26px;
  }
  .hero-content h1 .h1-lead {
    font-size: 23px;
  }
  .hero-eyebrow {
    white-space: normal;
    max-width: 340px;
  }
  /* On a narrow/tall mobile viewport, "cover" sizing crops out the
     face (it sits toward the right of the source photo) when
     centered horizontally. Shift the focal point right and toward
     the top so her face stays in frame like the desktop crop. */
  .hero-image {
    background-position: 62% 4%;
  }
  .header-inner {
    flex-wrap: wrap;
    row-gap: 10px;
  }
  .main-nav {
    display: none;
  }
  /* Target mobile header shows a single CTA — the secondary
     "資料ダウンロード" button is desktop-only real estate. */
  .header-buttons .btn-purple {
    display: none;
  }
  .hero-stats {
    justify-content: flex-start;
    flex-wrap: wrap;
    gap: 10px;
  }
  .hero-features {
    gap: 28px;
    justify-content: flex-start;
  }
}

/* Phone width: show the three stat circles side by side above the
   CTA button (desktop/tablet keep the button-then-circles order
   from the HTML). .hero-content becomes display:contents so its
   children can be freely reordered alongside .hero-stats as flex
   items of .hero-overlay. */
@media (max-width: 620px) {
  .hero-content {
    display: contents;
  }

  .hero-eyebrow {
    order: 1;
    margin-top: 36px;
  }

  .hero-content h1 {
    order: 2;
  }

  .hero-description {
    order: 3;
  }

  .hero-stats {
    order: 4;
    justify-content: space-between;
    flex-wrap: nowrap;
    width: 100%;
    gap: 8px;
    margin-top: 4px;
  }

  .hero-stat {
    width: calc((100% - 16px) / 3);
    height: auto;
    aspect-ratio: 1 / 1;
    grid-template-rows: 14px 1fr;
    row-gap: 2px;
    padding: 13px 6px 7px;
  }

  .hero-stat .stat-label {
    font-size: 9px;
  }

  .hero-stat strong {
    font-size: 13px;
    line-height: 22px;
  }

  /* The big colored digits (<em>) weren't scaled down with the
     rest of the stat text, so each circle's content block ended
     up a different height depending on how many oversized-digit
     lines it had — which shifted the "COACH" / "PROGRAM" /
     "2026 AUG" labels above them out of alignment with each other
     even though the circles center their content as a group. */
  .hero-stat strong em {
    font-size: 20px;
    line-height: 22px;
  }

  .hero-stat:first-child strong em {
    font-size: 14px;
    line-height: 22px;
  }

  .hero-cta {
    order: 5;
    margin-top: 22px;
  }

  .hero-note {
    order: 6;
  }
}

/* =========================================================
   SECTION 02 — WHO IT'S FOR
   ========================================================= */

#service {
  width: 100%;
  min-height: 1207.5px;
  padding: 73.5px 49px 84px;
  background: linear-gradient(135deg, #f6f9fd, #eef4fb);
}

#service > .section-heading,
#service > .circle-cards,
#service > .check-list-box,
#service > .section-bottom-text {
  width: min(100%, 1365px);
  margin-left: auto;
  margin-right: auto;
}

/* ---------------------------------------------------------
   Section heading
--------------------------------------------------------- */

#service .section-heading {
  text-align: center;
  margin-bottom: 28px;
}

#service .section-label {
  margin: 0 0 16px;
  color: #18a2ac;
  font-family: "Zen Maru Gothic", "Zen Kaku Gothic New", sans-serif;
  font-size: 21px;
  font-weight: 700;
  line-height: 1.3;
  letter-spacing: 0.04em;
}

#service .section-heading h2 {
  margin: 0;
  color: #323b4d;
  font-size: 44px;
  font-weight: 500;
  line-height: 1.5;
  letter-spacing: 0.035em;
}

#service .section-heading > p:last-child {
  margin: 17.5px auto 0;
  color: #486e7f;
  font-size: 17.5px;
  line-height: 1.8;
}


/* ---------------------------------------------------------
   Three circular image placeholders
--------------------------------------------------------- */

#service .circle-cards {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  align-items: start;
  gap: 52.5px;
  margin-top: 24.5px;
  margin-bottom: 38.5px;
}

#service .circle-card {
  min-width: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
}

#service .circle-image {
  width: 339.5px;
  height: 339.5px;
  flex: 0 0 339.5px;
  border-radius: 50%;
  overflow: hidden;

  display: flex;
  align-items: center;
  justify-content: center;

  background:
    linear-gradient(
      135deg,
      #dce8f0,
      #eef3f6
    );

  color: #9fb0bd;
  font-size: 19px;
  font-weight: 700;
  letter-spacing: 0.08em;
}

#service .circle-card:nth-child(1) .circle-image {
  background-image: url('data:image/png;base64,');
  background-size: cover;
  background-position: center;
}

#service .circle-card:nth-child(2) .circle-image {
  background-image: url('data:image/png;base64,');
  background-size: cover;
  background-position: center;
}

#service .circle-card:nth-child(3) .circle-image {
  background-image: url('data:image/png;base64,');
  background-size: cover;
  background-position: center top;
}

#service .circle-card .circle-image span {
  display: none;
}

#service .circle-card-label {
  width: max-content;
  max-width: 100%;
  margin-top: -2px;
  padding: 14px 31.5px;

  border-radius: 1748px;
  background: #7d93c7;

  color: #ffffff;
  font-size: 21px;
  font-weight: 700;
  line-height: 1.35;
  text-align: center;

  white-space: nowrap;
}


/* ---------------------------------------------------------
   White checklist box
--------------------------------------------------------- */

#service .check-list-box {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));

  column-gap: 84px;
  row-gap: 21px;

  padding: 35px 44px;

  border-radius: 14px;
  background: #ffffff;
}

#service .check-column {
  min-width: 0;
}

#service .check-column p {
  position: relative;

  margin: 0;
  padding-left: 33px;

  color: #486e7f;
  font-size: 17.5px;
  font-weight: 500;
  line-height: 1.7;
  letter-spacing: 0.01em;
}

#service .check-column p + p {
  margin-top: 17.5px;
}

/* Blue checkmark */

#service .check-column p::first-letter {
  color: #18a2ac;
  font-weight: 700;
}


/* ---------------------------------------------------------
   Bottom explanatory text
--------------------------------------------------------- */

#service .section-bottom-text {
  margin-top: 44px;
  text-align: center;
}

#service .section-bottom-text h3 {
  margin: 0 0 14px;

  color: #3d4857;
  font-size: 21px;
  font-weight: 500;
  line-height: 1.5;
}

#service .section-bottom-text h3::first-letter {
  color: #3EABD3;
}

#service .section-bottom-text p {
  margin: 0;

  color: #486e7f;
  font-size: 16px;
  line-height: 1.9;
  letter-spacing: 0.02em;
}

#service .section-bottom-text p + p {
  margin-top: 0;
}


/* =========================================================
   SECTION 02 — RESPONSIVE
   ========================================================= */

@media (max-width: 1365px) {

  #service {
    padding: 91px 35px 77px;
  }

  #service .section-heading h2 {
    font-size: 42px;
  }

  #service .circle-cards {
    gap: 31.5px;
  }

  #service .circle-image {
    width: min(27vw, 306px);
    height: min(27vw, 306px);
    flex-basis: min(27vw, 306px);
  }

  #service .circle-card-label {
    padding: 12px 21px;
    font-size: 19px;
  }

  #service .check-list-box {
    column-gap: 44px;
    padding: 31.5px 35px;
  }
}


@media (max-width: 980px) {

  #service {
    padding: 80.5px 28px 73.5px;
  }

  #service .section-heading h2 {
    font-size: 37px;
  }

  #service .section-heading > p:last-child {
    font-size: 16px;
  }

  #service .circle-cards {
    gap: 14px;
    margin-top: 31.5px;
  }

  #service .circle-image {
    width: calc((100vw - 94.5px) / 3);
    height: calc((100vw - 94.5px) / 3);
    flex-basis: calc((100vw - 94.5px) / 3);
  }

  #service .circle-card-label {
    width: 100%;
    padding: 12px 7px;
    font-size: 16px;
    white-space: normal;
  }

  #service .check-list-box {
    grid-template-columns: 1fr;
    row-gap: 16px;
    padding: 30px 30px;
  }

  #service .check-column p {
    font-size: 16px;
  }

  #service .check-column p + p {
    margin-top: 12px;
  }

  #service .section-bottom-text {
    margin-top: 38.5px;
  }

  #service .section-bottom-text h3 {
    font-size: 19px;
  }

  #service .section-bottom-text p {
    font-size: 14px;
  }
}

/* Mobile/tablet only: circle-cards becomes a 2-up top row (cards 1 & 3)
   with card 2 centered underneath — matching the target mobile design.
   All three circles share one uniform size and caption spacing so
   nothing overlaps. Desktop/tablet-landscape layouts above are untouched. */
@media (max-width: 620px) {
  #service .circle-cards {
    grid-template-columns: 1fr 1fr;
    grid-template-areas:
      "c1 c3"
      "c2 c2";
    row-gap: 20px;
    column-gap: 14px;
  }

  #service .circle-card:nth-child(1) {
    grid-area: c1;
  }

  #service .circle-card:nth-child(3) {
    grid-area: c3;
  }

  #service .circle-card:nth-child(2) {
    grid-area: c2;
    position: relative;
    z-index: 1;
  }

  #service .circle-image,
  #service .circle-card:nth-child(2) .circle-image {
    width: min(30vw, 140px);
    height: min(30vw, 140px);
    flex-basis: min(30vw, 140px);
  }

  #service .circle-card-label,
  #service .circle-card:nth-child(2) .circle-card-label {
    width: max-content;
    max-width: 100%;
    margin-top: 10px;
    white-space: normal;
    text-align: center;
  }
}

/* =========================================================
   SECTION 03 — ABOUT / 8 AREAS
   ========================================================= */

#about {
  width: 100%;
  min-height: 1120px;
  padding: 77px 49px 105px;
  background: linear-gradient(135deg, #fbfcfe, #f4f7fc);
}


/* ---------------------------------------------------------
   SECTION HEADING
--------------------------------------------------------- */

#about > .section-heading {
  width: 100%;
  max-width: 1575px;
  margin: 0 auto 42px;
  text-align: center;
