}


/* =========================================================
   COMPARISON TABLE
   ========================================================= */

.counseling-section .comparison-table {
  width: 100%;
  max-width: 1120px;

  margin: 0 auto;

  border-collapse: collapse;
  border-spacing: 0;

  table-layout: fixed;

