  }

}


/* =========================================================
   TABLET
   ========================================================= */

@media (max-width: 1330px) {

  .counseling-section {
    padding-left: 35px;
    padding-right: 35px;
  }

  .counseling-section .support-flow {
    max-width: 1120px;
  }

  .counseling-section .comparison-table {
    max-width: 1120px;
  }

  .counseling-section .info-box {
    max-width: 1120px;
  }

}


/* =========================================================
   SMALL TABLET / MOBILE
   ========================================================= */

@media (max-width: 1050px) {

  .counseling-section {
    padding: 73.5px 28px 70px;
  }

  .counseling-section .section-heading h2 {
    font-size: 37px;
  }

  .counseling-section .support-flow {
    padding-left: 24.5px;
    padding-right: 24.5px;
  }

  .counseling-section .support-box > strong {
    font-size: 16px;
  }

  .counseling-section .support-box > small {
    font-size: 11.5px;
  }

  .counseling-section .support-highlight > strong {
    font-size: 23px;
  }

