/* =========================================================
   WEEK BLOCK
   ========================================================= */

.ninety-section .weeks {
  min-width: 0;
  height: 98px;

  padding: 12px;

  box-sizing: border-box;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
