   ========================================================= */

.measure-section {
  width: 100%;
  padding: 80.5px 49px 91px;
  background: linear-gradient(135deg, #f6f9fd, #eef4fb);
}

.measure-section .section-heading {
  width: 100%;
  max-width: 1085px;
  margin: 0 auto 35px;
  text-align: center;
}

.measure-section .section-label {
  margin: 0 0 16px;
  color: #18a2ac;
  font-family: "Zen Maru Gothic", "Zen Kaku Gothic New", sans-serif;
  font-size: 19px;
