  letter-spacing: 0.04em;
}

.measure-section .section-heading h2 {
  margin: 0;
  color: #323b4d;
  font-size: 41px;
  font-weight: 500;
  line-height: 1.5;
  letter-spacing: 0.025em;
}

.measure-section .section-heading > p:last-child {
  margin: 16px auto 0;
  color: #486e7f;
  font-size: 16.5px;
  line-height: 1.8;
}

/* ---- measurement scale ---- */

.measure-section .measurement-scale {
  width: 100%;
  max-width: 1575px;
  margin: 0 auto;

  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 5px;
}

.measure-section .measurement-scale > div {
  min-width: 0;
  padding: 21px 14px;
  background: #e3eaf2;
  text-align: center;
}

.measure-section .measurement-scale > div:nth-child(3) {
  background: #ffffff;
  box-shadow: 0 10.5px 28px rgba(30, 50, 80, 0.08);
}

.measure-section .measurement-scale > div.positive {
  background: #fff8ef;
}

.measure-section .measurement-scale strong {
  display: block;
  color: #323b4d;
  font-size: 26px;
  font-weight: 700;
  margin-bottom: 9px;

  /* The "-"/"+" sign glyphs and digits don't share the same
     advance width in this font by default, so "-2"/"-1"/"0"/"+1"/
     "+2" render with their visible ink starting at slightly
     different x positions even though the boxes themselves line
     up. tabular-nums (with the tnum feature as a fallback for
     wider support) forces all of them to the same fixed width. */
  font-variant-numeric: tabular-nums;
  font-feature-settings: "tnum" 1;
}

.measure-section .measurement-scale > div:nth-child(3) strong {
  font-size: 30px;
}

.measure-section .measurement-scale > div.positive strong {
  color: #d98a54;
}

.measure-section .measurement-scale span {
  display: block;
  color: #486e7f;
  font-size: 15.5px;
  line-height: 1.4;
}

/* ---- arrow + caption ---- */

.measure-section .measurement-arrow {
  position: relative;
  width: 100%;
  max-width: 1575px;
  margin: 28px auto 0;
  padding-top: 21px;

  color: #486e7f;
  font-size: 15px;
  line-height: 1.8;
  text-align: center;
}

.measure-section .measurement-arrow::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 2px;
  background: linear-gradient(to right, #8fa9d0, #e3a878);
}

.measure-section .measurement-arrow::after {
  content: '';
  position: absolute;
  top: -5px;
  right: 0;
  width: 0;
  height: 0;
  border-top: 6px solid transparent;
  border-bottom: 6px solid transparent;
  border-left: 9px solid #e3a878;
}

/* ---- measure content (image + text) ---- */

.measure-section .measure-content {
  width: 100%;
  max-width: 1575px;
  margin: 38.5px auto 0;

  display: grid;
  grid-template-columns: 411px minmax(0, 1fr);
  gap: 42px;
  align-items: start;
}

.measure-section .measure-image {
  width: 100%;
  height: 499px;
  border-radius: 17.5px;
  background-image: url('data:image/png;base64,');
  background-size: cover;
  background-position: center 30%;
}

.measure-section .measure-image span {
  display: none;
}

.measure-section .measure-text h3 {
  color: #323b4d;
  font-size: 26px;
  font-weight: 500;
  line-height: 1.5;
  margin-bottom: 17.5px;
}

.measure-section .measure-text p {
  color: #486e7f;
  font-size: 16.5px;
  line-height: 1.85;
  margin-bottom: 21px;
}

.measure-section .measure-text ul {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.measure-section .measure-text li {
  position: relative;
  padding-left: 28px;
  color: #486e7f;
  font-size: 16.5px;
  line-height: 1.6;
}

.measure-section .measure-text li::before {
  content: '✓';
  position: absolute;
  left: 0;
  top: 0;
  color: #18a2ac;
  font-size: 17.5px;
  font-weight: 700;
}

@media (max-width: 735px) {
  .measure-section .measurement-scale {
    grid-template-columns: repeat(3, minmax(0, 1fr));
    row-gap: 7px;
  }
  .measure-section .measure-content {
    grid-template-columns: 1fr;
  }
  .measure-section .measure-image {
    height: 350px;
  }
}

/* Phone-width only: the -2..+2 scale becomes a single vertical
   stack (one row per score) with a continuous arrow running down
   the left side, matching the target mobile design. The 3-column
   tablet layout above (max-width:735px) is untouched down to
   this breakpoint. */
@media (max-width: 620px) {
  .measure-section .measurement-scale {
    grid-template-columns: 1fr;
    row-gap: 8px;
    position: relative;
    padding-left: 26px;
  }

  .measure-section .measurement-scale::before {
    content: '';
    position: absolute;
    left: 6px;
    top: 6px;
    bottom: 14px;
    width: 2px;
    background: linear-gradient(to bottom, #8fa9d0, #e3a878);
  }

  .measure-section .measurement-scale::after {
    content: '';
    position: absolute;
    left: 1px;
    bottom: 6px;
    width: 0;
    height: 0;
    border-left: 6px solid transparent;
    border-right: 6px solid transparent;
    border-top: 9px solid #e3a878;
  }

  .measure-section .measurement-scale > div {
    display: flex;
    align-items: center;
    gap: 14px;
    text-align: left;
    padding: 14px 16px;
  }

  .measure-section .measurement-scale strong {
    margin-bottom: 0;
    min-width: 34px;
    text-align: center;
  }

  .measure-section .measurement-scale span {
    text-align: left;
  }

  /* Only the vertical arrow beside the scale is needed here — the
     horizontal gradient line + arrowhead decorating the caption
     text below becomes redundant (and visually competes with it)
     once the scale itself is vertical. Keep the caption text. */
  .measure-section .measurement-arrow::before,
  .measure-section .measurement-arrow::after {
    display: none;
  }

  .measure-section .measurement-arrow {
    padding-top: 0;
  }
}

