  gap: 10.5px;
  padding: 24.5px 28px;
  color: #323b4d;
  font-size: 18.5px;
  font-weight: 700;
}

.faq-section .faq-item summary::-webkit-details-marker {
  display: none;
}

.faq-section .faq-item summary > span:first-child {
  color: #18a2ac;
  font-weight: 700;
  flex-shrink: 0;
}

.faq-section .faq-arrow {
  margin-left: auto;
  color: #486e7f;
  font-size: 17.5px;
  flex-shrink: 0;
}

.faq-section .faq-answer {
  padding: 0 28px 28px 28px;
  border-top: 2px solid #eef1f5;
  margin-top: -3.5px;
  padding-top: 21px;

