/* =========================================================
   TABLET-RANGE HEADING SCALING
   Work / Measure / Coach / Compare / Price never had any
   responsive size step between their ~40-42px desktop size
   and the small mobile size set at 480px below, so through
   this whole tablet range (roughly 500-900px) they wrapped
   progressively worse with nothing to catch it — Compare's
   heading reached 4 lines by 560px. This adds the missing
   middle step.
   ========================================================== */

@media (max-width: 900px) {
  .work-section .section-heading h2,
  .coach-section .section-heading h2,
  .price-section .section-heading h2 {
    font-size: 30px;
  }

  .measure-section .section-heading h2 {
    font-size: 24px;
  }

  .compare-section .section-heading h2 {
    font-size: 26px;
  }
}

@media (max-width: 620px) {
  /* These section headings never got a mobile size reduction at
     all (unlike #about / .why-section / .counseling-section, which
     already step down around 35-37px at 840px). At 40-42px on a
     real phone they wrap 3-5 lines instead of 1-2. Triggered at
     620px (rather than down at 480px) so there's no awkward gap
     between this and the 900px tablet step above, where the
     30/24/26px tablet sizes were still just a bit too big. */
  .work-section .section-heading h2,
  .price-section .section-heading h2,
  .getting-started .section-heading h2,
  .faq-section .section-heading h2 {
    font-size: 20px;
    line-height: 1.5;
  }

  /* Coach's heading text runs slightly longer than the others in
     this group, so it needs to be a touch smaller to fit in one
     line too. */
  .coach-section .section-heading h2 {
    font-size: 18px;
    line-height: 1.5;
  }

  /* Measure's heading also has a manual break, and its first line
     is the longest of the group — needs to run smaller still. */
  .measure-section .section-heading h2 {
    font-size: 15px;
    line-height: 1.5;
  }

  /* Compare's heading has a manual line break after "どこでも" —
     its second line is a touch longer than the others', so it
     needs a slightly smaller size to stay on one line too. */
  .compare-section .section-heading h2 {
    font-size: 17px;
    line-height: 1.5;
  }
}

@media (max-width: 480px) {
  .final-cta-overlay h2 {
    font-size: 16px;
  }

  /* The "kimochi コーチング" wordmark used as the last column header
     in the two comparison tables scales off the same font-size as
     the rest of that header, and at real phone widths the column is
     too narrow to hold it — the logo graphic was spilling past the
     table edge. Shrink it specifically at this breakpoint. */
  .counseling-section .comparison-table thead th:last-child,
  .compare-section .comparison-table thead th:last-child {
    font-size: 9px;
  }

  /* The "About" 8-card grid stays 2-up all the way down to phone
     widths, leaving each card too narrow for its heading/bullets
     to sit comfortably. Drop to a single column here. */
  #about .about-grid {
    grid-template-columns: 1fr;
  }

  /* Icon-left / text-right layout for phone width. Grid areas let
     the icon, heading, and bullet list (three separate DOM
     children) form a two-column layout — icon on the left,
     heading+list stacked on the right — without touching the HTML.
     Desktop/tablet keep the centered icon-on-top card above. */
  #about .about-card {
    display: grid;
    grid-template-columns: 92px 1fr;
    grid-template-areas:
      "img title"
      "img list";
    column-gap: 16px;
    row-gap: 6px;
    align-items: center;

    min-height: 0;
    padding: 20px 18px;

    text-align: left;
  }

  #about .about-image-placeholder {
    grid-area: img;
    width: 92px;
    height: 92px;
    min-height: 92px;
    margin: 0;
    justify-self: center;
    align-self: center;
    overflow: hidden;
  }

  #about .about-card .about-image-placeholder {
    background-size: 68px auto !important;
  }

  #about .about-card h3 {
    grid-area: title;
    width: auto;
    margin: 0;
    text-align: left;
  }

  #about .about-card ul {
    grid-area: list;
    text-align: left;
  }

  /* Main price figure had no mobile sizing at all, so "円(税込)"
     was wrapping onto its own line under the price. */
  .price-section .main-price {
    font-size: 34px;
  }

  .price-section .main-price span {
    font-size: 15px;
  }

  /* Header: less outer padding frees up room, and the two CTA
     buttons shrink enough to actually fit side by side instead
     of running off the right edge of the screen. */
  .site-header {
    padding: 14px 20px;
  }

  .header-buttons .btn {
    font-size: 12px;
    padding: 9px 14px;
  }

  /* Hero CTA: same fixed size regardless of viewport used to push
     the button wider than a small phone screen. */
  .hero-cta {
    width: 100%;
    box-sizing: border-box;
    justify-content: center;
    font-size: 16px;
    padding: 15px 20px;
  }

  /* "kimochiコーチングでは…" heading: the wordmark + trailing text
     were both forced to a single non-wrapping line, which is wider
     than a small phone screen. Let it wrap and drop a size. */
  .why-section .why-right h3 .why-coaching-text,
  .why-section .why-right h3 .why-dewa-text {
    font-size: 19px;
    white-space: normal;
  }

  /* Force a line break inside each heading (after "ひとりで" on the
     left, after the kimochi logo on the right) so the illustration
     stays floated beside the heading — matching the full-width
     layout — instead of dropping below it. The
     <br class="why-mobile-break"> markers in the HTML are hidden
     everywhere except this width (see base rule near the heading
     styles). */
  .why-section .why-mobile-break {
    display: block;
  }

  .why-section .why-side h3 {
    padding-right: 108px;
    font-size: 19px;
  }

  .why-section .why-right h3 {
    flex-wrap: wrap;
    white-space: normal;
  }

  .why-section .why-right h3 .why-logo {
    width: 118px;
    height: 24px;
  }

  .why-section .small-illustration {
    width: 96px;
    height: 64px;
    min-height: 64px;
    top: 30px;
    right: 16px;
  }

  .why-section .why-right .small-illustration {
    top: 30px;
    right: 16px;
  }

  /* The 90-day timeline was still using its desktop 3-column
     layout (fixed 105px side badges + a squeezed middle column)
     at phone widths, forcing all 10 week pills into one unreadable
     row. Stack DAY0 / weeks / DAY90 vertically instead, and let
     the week grid wrap to two rows of five like the design intends. */
  .ninety-section .program-timeline {
    grid-template-columns: 1fr;
    height: auto;
    gap: 10px;
  }

  .ninety-section .timeline-start,
  .ninety-section .timeline-end,
  .ninety-section .weeks {
    height: auto;
  }

  .ninety-section .timeline-start,
  .ninety-section .timeline-end {
    flex-direction: row;
    justify-content: center;
    gap: 8px;
    padding: 12px;
  }

  .ninety-section .timeline-start span,
  .ninety-section .timeline-end span {
    margin-bottom: 0;
  }

  .ninety-section .weeks-grid {
    grid-template-columns: repeat(5, minmax(0, 1fr));
    gap: 6px;
  }

  .ninety-section .weeks-grid span {
    font-size: 12px;
    height: 32px;
  }

  /* Timeline notes: at this width the flex row layout was cramming
     the bullet, bold label, and full sentence onto one line,
     causing overlap. Let it wrap as a normal block of text instead. */
  .ninety-section .timeline-notes p {
    display: block;
    height: auto;
    min-height: 0;
  }
}

